            </View>
            <Pressable testID="add" style={styles.add} onPress={addToCart}><Text style={styles.addT}>+</Text></Pressable>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, backgroundColor: "#f8fafc" },
  header: { flexDirection: "row", justifyContent: "space-between", alignItems: "center", padding: 16, backgroundColor: "#2563eb" },
